package findu.backend.review.service;import findu.backend.review.dto.*;import findu.backend.review.entity.Review;import findu.backend.review.repository.ReviewRepository;import findu.backend.user.entity.User;import findu.backend.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;@Service @RequiredArgsConstructor public class ReviewService{final ReviewRepository repo;final UserRepository users;@Transactional public ReviewResponse create(Long uid, ReviewCreateRequest r){User reviewer=users.findById(uid).orElseThrow(()->new IllegalArgumentException("사용자를 찾을 수 없습니다."));User reviewee=users.findById(r.revieweeId()).orElseThrow(()->new IllegalArgumentException("대상 사용자를 찾을 수 없습니다."));if(uid.equals(r.revieweeId()))throw new IllegalArgumentException("본인에게 리뷰를 작성할 수 없습니다.");Review x=repo.save(Review.builder().reviewer(reviewer).reviewee(reviewee).rating(r.rating()).comment(r.comment()).build());int delta=r.rating()>=4?2:r.rating()<=2?-2:0;reviewee.updateTrustScore(Math.max(0,reviewee.getTrustScore()+delta));return ReviewResponse.from(x);}@Transactional(readOnly=true)public List<ReviewResponse> list(Long uid){return repo.findByRevieweeIdOrderByCreatedAtDesc(uid).stream().map(ReviewResponse::from).toList();}}
